&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Nous recrutons un&amp;nbsp;&lt;strong&gt;Consultant Senior&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Transformation, Marketing &amp;amp; Expérience Client&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;pour rejoindre notre Practice Business Consulting.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
