&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Définir la vision stratégique et les roadmaps&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Identifier des opportunités et use&amp;nbsp;cases innovants&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Concevoir des&amp;nbsp;stratégies d’engagement et des&amp;nbsp;parcours clients,&amp;nbsp;en en mesurant&amp;nbsp;les impacts&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Repenser&amp;nbsp;les process et les organisations, notamment&amp;nbsp;dans des contextes d’intégration de l’IA&amp;nbsp;/ de l’agentique&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Piloter la mise en œuvre opérationnelle des initiatives, du lancement à la mise à l’échelle&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Accompagner les équipes clientes dans le changement et l’adoption&amp;nbsp;des outils&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Mesurer la performance et le ROI pour assurer le succès durable&amp;nbsp;des actions déployées&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Votre profil&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
