&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Accédez à des outils d’IA pour booster votre créativité et votre efficacité&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Intégrez une équipe enthousiaste, bienveillante et soudée&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Vous êtes&amp;nbsp;prêt.e&amp;nbsp;à relever des défis stratégiques&amp;nbsp;au cœur des enjeux de demain&amp;nbsp;?&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Postulez dès maintenant et rejoignez l’aventure WPP Enterprise Solutions&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;!&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
