&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Strong Presentation skills and experience working with C-Level Executives and Directors.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Strong technical focus and detailed knowledge of Microsoft Office Applications.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Superb personal organizational skills to ensure all client commitments are met.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Customer focused.  Able to deliver extremely high levels of customer satisfaction.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Able to perform well in the face of tight deadlines and tough technical and organizational challenges.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Reasonable travel required&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6}&quot;&gt;&amp;nbsp;&lt;br&gt;&lt;br&gt;&lt;/span&gt;
&lt;p style=&quot;margin: 0in; font-family: Calibri; font-size: 11.0pt; color: #979797;&quot;&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;#LI-SM1&lt;/span&gt;&lt;/p&gt;
&lt;p lang=&quot;en-AU&quot; style=&quot;margin: 0in; font-family: Calibri; font-size: 11.0pt; color: #979797;&quot;&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;#LI-Hybrid&lt;/span&gt;&lt;/p&gt;
&lt;span data-ccp-props=&quot;{&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6}&quot;&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;About Us&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;Diligent is the AI leader in governance, risk and compliance (GRC) SaaS solutions, helping more than 1 million users and 700,000 board members to clarify risk and elevate governance. The Diligent One Platform gives practitioners, the C-Suite and the board a consolidated view of their entire GRC practice so they can more effectively manage risk, build greater resilience and make better decisions, faster.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;div&gt;&lt;span data-teams=&quot;true&quot;&gt;At Diligent, we&#39;re building the future with people who think boldly and move fast. &amp;nbsp;Whether you&#39;re designing systems that leverage large language models or part of a team reimaging workflows with AI, you&#39;ll help us unlock entirely new ways of working and thinking. &amp;nbsp;Curiosity is in our DNA, we look for individuals willing to ask the big questions and experiment fearlessly - those who embrace change not as a challenge, but as an opportunity. &amp;nbsp;The future belongs to those who keep learning, and we are building it together. &amp;nbsp;At Diligent, you’re not just building the future - you’re an agent of positive change, joining a global community on a mission to make an impact.&lt;/span&gt;&lt;/div&gt;
&lt;p&gt;Learn more at&amp;nbsp;diligent.com or follow us on&amp;nbsp;&lt;u&gt;&lt;a id=&quot;OWA170dad44-6a69-e1e1-d720-601cd59ec77c&quot; class=&quot;x_x_x_OWAAutoLink&quot; href=&quot;https://www.linkedin.com/company/diligent-board-member-services/mycompany/verification/&quot; data-outlook-id=&quot;c606bc91-5052-4d3a-a1d1-ed00ede365d9&quot; data-linkindex=&quot;1&quot; data-auth=&quot;NotApplicable&quot;&gt;LinkedIn&lt;/a&gt;&lt;/u&gt;&amp;nbsp;and&amp;nbsp;&lt;u&gt;&lt;a id=&quot;OWA153deb8c-7641-f6fc-97cb-65df680002a3&quot; class=&quot;x_x_x_OWAAutoLink&quot; href=&quot;https://www.facebook.com/DiligentCorporation/&quot; data-outlook-id=&quot;07f4e461-6294-4482-a624-e58c27cd6199&quot; data-linkindex=&quot;2&quot; data-auth=&quot;NotApplicable&quot;&gt;Facebook&lt;/a&gt;&lt;/u&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What Diligent Offers You&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Creativity is ingrained in our culture.&lt;/strong&gt; We are innovative collaborators by nature. We thrive in exploring how things can be differently both in our internal processes and to help our clients&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;We care about our people.&amp;nbsp;&lt;/strong&gt;Diligent offers a flexible work environment, global days of service, comprehensive health benefits, meeting free days, generous time off policy and wellness programs&amp;nbsp;to name a few&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;We have teams all over the world&lt;/strong&gt;. We may be headquartered in New York City, but we have office hubs in Washington D.C., Vancouver, London, Galway, Budapest, Munich, Bengaluru, Singapore, and Sydney.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Diversity is important to us.&lt;/strong&gt; Growing, maintaining and promoting a diverse team is a top priority for us. We foster and encourage diversity through our Employee Resource Groups and provide access to resources and education to support the education of our team, facilitate dialogue, and foster understanding.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Diligent created the modern governance movement. Our world-changing idea is to empower leaders with the technology, insights and connections they need to drive greater impact and accountability – to lead with purpose. Our employees are passionate, smart, and creative people who not only want to help build the software company of the future, but who want to make the world a more sustainable, equitable and better place.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Headquartered in New York, Diligent has offices in Washington D.C.,&amp;nbsp; London, Galway, Budapest, Vancouver, Bengaluru, Munich, Singapore and Sydney.  &amp;nbsp;To foster strong collaboration and connection, this role will follow a hybrid work model. If you are within a commuting distance to one of our Diligent office locations, you will be expected to&amp;nbsp;&lt;strong&gt;work onsite at least 50% of the time.&lt;/strong&gt;&amp;nbsp;We believe that in-person engagement helps drive innovation, teamwork, and a strong sense of community.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;Diligent is proud to be an equal opportunity employer. We do not discriminate based on race, color, religious creed, sex, national origin, ancestry, citizenship status, pregnancy, childbirth, physical disability, mental disability, age, military status, protected veteran status, marital status, registered domestic partner or civil union status, gender (including sex stereotyping and gender identity or expression), medical condition (including, but not limited to, cancer related or HIV/AIDS related), genetic information, or sexual orientation in accordance with applicable federal, state and local laws.&amp;nbsp;We also consider qualified applicants regardless of criminal histories, consistent with legal requirements. See also&amp;nbsp;Diligent&#39;s&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://www.diligent.com/company/eeo-policy&quot; data-auth=&quot;NotApplicable&quot; data-outlook-id=&quot;5e90c823-c220-4ada-92af-0b9df69068d6&quot; data-linkindex=&quot;4&quot;&gt;EEO Policy&lt;/a&gt;&amp;nbsp;and&amp;nbsp;&lt;a href=&quot;https://www.diligent.com/-/media/project/diligent/master/eeo-is-the-law-poster-eeocselfprintposter-and-ofccp-supplement-from-20170719.pdf?rev=96fafda8-f51d-44b6-a380-9af42898f526&amp;amp;hash=614AE342F4AB51A091EA3E15F84F7E49&quot; data-auth=&quot;NotApplicable&quot; data-outlook-id=&quot;25527b37-a96e-4ef3-af1f-248e2a881a45&quot; data-linkindex=&quot;5&quot;&gt;US EEOC&lt;/a&gt;&lt;a href=&quot;https://www.diligent.com/-/media/project/diligent/master/eeo-is-the-law-poster-eeocselfprintposter-and-ofccp-supplement-from-20170719.pdf?rev=96fafda8-f51d-44b6-a380-9af42898f526&amp;amp;hash=614AE342F4AB51A091EA3E15F84F7E49&quot; data-auth=&quot;NotApplicable&quot; data-outlook-id=&quot;25527b37-a96e-4ef3-af1f-248e2a881a45&quot; data-linkindex=&quot;6&quot;&gt;’&lt;/a&gt;&lt;a href=&quot;https://www.diligent.com/-/media/project/diligent/master/eeo-is-the-law-poster-eeocselfprintposter-and-ofccp-supplement-from-20170719.pdf?rev=96fafda8-f51d-44b6-a380-9af42898f526&amp;amp;hash=614AE342F4AB51A091EA3E15F84F7E49&quot; data-auth=&quot;NotApplicable&quot; data-outlook-id=&quot;25527b37-a96e-4ef3-af1f-248e2a881a45&quot; data-linkindex=&quot;7&quot;&gt;s Know Your Rights&lt;/a&gt;. We are a drug free workplace.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;We are committed to providing reasonable accommodations for qualified individuals with disabilities and disabled veterans in our job application procedures. If you need assistance or an accommodation due to a disability, you may contact us at -----
&lt;div&gt;To support a fair and consistent hiring&amp;nbsp;process, we use AI&amp;nbsp;and digital automated tools to assist our recruitment team in organizing candidate data, surfacing relevant applications, coordinating&amp;nbsp;interview scheduling and summarizing interview notes. All final screening, evaluation, and hiring decisions are made by humans on our team. To learn more about how we collect, protect, and process your information, please review our&amp;nbsp;&lt;a href=&quot;https://www.diligent.com/legal/candidate-privacy&quot; data-auth=&quot;NotApplicable&quot; data-outlook-id=&quot;48c7a45d-2b3c-4bc9-99ec-639351abe71c&quot; data-linkindex=&quot;8&quot;&gt;Candidate Privacy Policy&lt;/a&gt;. &amp;nbsp;&lt;/div&gt;
&lt;div&gt;At Diligent, we recognize the value of a diverse global workforce. Visa sponsorship may be available for select positions based on business needs and specific role requirements. Sponsorship decisions are evaluated on a case-by-case basis, and eligibility should not be assumed for all opportunities.&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Recruitment agencies:&lt;/strong&gt; Diligent does not accept unsolicited agency resumes. Please do not forward resumes to our jobs alias, Diligent employees or any other organization location. Diligent is not responsible for any fees related to unsolicited resumes&lt;/div&gt;&lt;/div&gt;Find Jobs in Germany on Arbeitnow

&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A career driven by you. &lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Join AutoScout24 Group and experience life in the fast lane. We’re not just leading the market; we’re creating it. We’re constantly innovating, evolving and transforming things for our customers. We’re driven, ambitious and determined to do our best work, together. For a career that doesn’t stand still, where you can put your ideas in the driving seat and change the way the world moves, join our international community.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:257}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p class=&quot;p1&quot;&gt;Join our Product Management team in designing and managing the product vision. You’ll work independently, setting the&amp;nbsp;north star, defining the scope, executing freely, and leading from behind. Consider it your own, mini-start-up. You’ll work&amp;nbsp;untethered, focused on the user, with modern tools in a dynamic environment.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What you’ll do:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li class=&quot;p1&quot;&gt;Define vision as well as business goals for the Engagement product area within the AutoScout24 buyer experience, focusing on driving user activation, engagement, and retention and translate them into a strategy and concrete product streams&lt;/li&gt;
&lt;li class=&quot;p1&quot;&gt;Develop a product roadmap and milestones that reflect expected engagement outcomes, using data insights and experimentation to inform prioritization&lt;/li&gt;
&lt;li class=&quot;p1&quot;&gt;Align priorities across the product organization with stakeholders, ensuring your work supports broader company goals&lt;/li&gt;
&lt;li class=&quot;p1&quot;&gt;Own the end-to-end product lifecycle in your cross-functional team: deeply understand the customer, develop hypotheses, validate ideas through A/B testing, and iterate based on results. Collaborate to craft culture with our top tier leadership team while mentoring and coaching PMs and those around you&lt;/li&gt;
&lt;li class=&quot;p1&quot;&gt;Establish, support, and ensure compliance of company product management methods and tools&lt;/li&gt;
&lt;li class=&quot;p1&quot;&gt;Define success metrics around engagement and retention, and regularly communicate performance, learnings, and impact across the organization&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What you’ll bring:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li class=&quot;p1&quot;&gt;Digital product management experience, preferably in Marketplaces or eCommerce&lt;/li&gt;
&lt;li class=&quot;p1&quot;&gt;Strong customer focus with proven track record of building products from MVP to “world-class” using insights from tracking, user testing and A/B tests&lt;/li&gt;
&lt;li class=&quot;p1&quot;&gt;Ideally knowledge in conversion rate optimisation (CRO) as well as testing frameworks and tools&lt;/li&gt;
&lt;li class=&quot;p1&quot;&gt;Very good analytical skills with the ability to use data to backup ideas and assumptions, develop insights and recommendations and define and measure success metrics&lt;/li&gt;
&lt;li class=&quot;p1&quot;&gt;Self-management, negotiation technique, conflict management and strategic thinking&lt;/li&gt;
&lt;li class=&quot;p1&quot;&gt;Strong business knowledge and team development experience&lt;/li&gt;
&lt;li class=&quot;p1&quot;&gt;Extensive know-how of common product management tools and knowledge of target groups&lt;/li&gt;
&lt;li class=&quot;p1&quot;&gt;Product and cross-departmental entrepreneurial thinking and acting&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A culture of growth&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;With over 50 nationalities represented, we’re proud to welcome people of all backgrounds to our growing community, and we’re always finding new ways to help people feel welcomed and included. Here, you’ll have the tools, training and support you need to work in a way that suits you, learn new skills and reach your potential.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;For a career where you can drive our business and shape your future, apply now.&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;Find Jobs in Germany on Arbeitnow

&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;&lt;strong&gt;A&lt;/strong&gt;&lt;strong&gt;BOUT TIDE&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;At Tide, we help SMEs save time and money in the running of their businesses by not only offering business accounts and related banking services, but also a comprehensive set of highly usable and connected administrative solutions, from invoicing to accounting.&lt;/p&gt;
&lt;p&gt;Tide is transforming the small business banking market and now supports over 2 million members globally across the UK, India, Germany and France.&lt;/p&gt;
&lt;p&gt;Using advanced technology, all solutions are designed with SMEs in mind. With quick onboarding, low fees and innovative features, we thrive on making data driven decisions to serve our mission: to help SMEs save time and money so they can get back to doing what they love.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Tide facts:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Tide is available for UK, Indian, German and French SMEs&lt;/li&gt;
&lt;li&gt;Over 2 million members: 900,000 UK and 1,100,000 in India and growing rapidly&lt;/li&gt;
&lt;li&gt;Over $300 million raised in funding&lt;/li&gt;
&lt;li&gt;Over 2,800 Tideans globally&lt;/li&gt;
&lt;li&gt;Recognised with Great Place to Work certification three years in a row, and among India’s Top 50 Best Workplaces in Banking, Financial Services, and Insurance in 2026&lt;/li&gt;
&lt;li&gt;We have offices in Central London, with a member support and technology centre in Sofia, Bulgaria, technology centres in Serbia, Romania, Lithuania and Hyderabad and offices in Gurugram, New Delhi, Berlin, Paris and Luxembourg&lt;/li&gt;
&lt;/ul&gt;&lt;/div&gt;&lt;h3&gt;&lt;strong&gt;Über das Team&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;Du wirst Teil eines engagierten Teams, das den Markterfolg von Tide in Deutschland ausbaut. Das Team bringt Expertise aus Finanzdienstleistungen, Technologie und lokalem Marktverständnis zusammen und gestaltet gemeinsam das Wachstum von Tide in Deutschland. Partner Credit Services ist der KMU-Kreditmarktplatz von Tide: In Zusammenarbeit mit Kreditpartnern vermitteln wir die passende Finanzierung für kleine und mittelgroße Unternehmen.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;Über die Rolle&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;Als Sales Executive bist Du Teil unseres Vertriebsteams und berichtest direkt an den Team Lead Sales. Du betreust ein bereits qualifiziertes, warmes Pipeline aus unserem CRM – Dein Fokus liegt darauf, diese Kunden kompetent zu beraten und zum Abschluss zu bringen. Zu Deinen Aufgaben gehören:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Kundeneinbindung:&lt;/strong&gt; Kontaktiere, binde ein und betreue unsere KMU-Kunden während des gesamten Kreditantragsprozesses&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Pipeline-Pflege:&lt;/strong&gt; Bearbeite kontinuierlich qualifizierte Leads aus unserem CRM und anderen Kanälen, um eine konsistente Sales Pipeline zu sichern&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Vertrauen aufbauen:&lt;/strong&gt; Erkläre überzeugend die verschiedenen Finanzierungsoptionen unserer Partner und bleib über Markt und Wettbewerb informiert&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Finanzierungsexpertise:&lt;/strong&gt; Erwirb ein tiefes Verständnis für die Vielfalt der Kreditgeber und Produkte am Markt&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Partner-Engagement:&lt;/strong&gt; Pflege aktiv die Beziehung und Abläufe mit unseren Kreditpartnern&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;CRM-Datenpflege:&lt;/strong&gt; Halte Kundeninformationen in Salesforce über alle Vertriebsstufen aktuell&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Teamkultur:&lt;/strong&gt; Teile Erfahrungen und Erfolge aktiv mit dem Team&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Wen suchen wir&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Wir suchen eine engagierte Persönlichkeit, die dazu beiträgt, Tide zur vertrauenswürdigsten KMU-Kreditplattform in Deutschland zu machen.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;Das bringst Du mit&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Vertriebsleidenschaft und echten Antrieb, Ziele zu erreichen&lt;/li&gt;
&lt;li&gt;Ausgezeichnete Kommunikations- und zwischenmenschliche Fähigkeiten&lt;/li&gt;
&lt;li&gt;Eine proaktive, ergebnisorientierte Arbeitsweise mit Fokus auf Genauigkeit und Umsetzungsgeschwindigkeit&lt;/li&gt;
&lt;li&gt;Organisationstalent und einen kühlen Kopf auch unter Druck, sowie die Fähigkeit, Probleme schnell und pragmatisch zu lösen&lt;/li&gt;
&lt;li&gt;Fließende, verhandlungssichere Deutschkenntnisse und gute Englischkenntnisse&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Das ist ein Plus, aber keine Voraussetzung:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Erfahrung im Fintech-, Banking-, Payments- oder Kreditbereich&lt;/li&gt;
&lt;li&gt;Erfahrung im Outbound-Vertrieb oder in der Kaltakquise – diese Energie schätzen wir sehr, auch wenn sich diese Rolle auf die Betreuung bereits qualifizierter, interessierter Kunden konzentriert&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Du musst nicht alle Punkte vollständig erfüllen – wenn Du Dich in der Beschreibung wiedererkennst, freuen wir uns auf Deine Bewerbung. Wir ermutigen insbesondere Frauen, sich für diese Position zu bewerben.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Gehalt:&lt;/strong&gt; 80.000–105.000 € OTE, je nach Erfahrung.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;Was bieten wir&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Bis zu 15% Provision auf den erreichten Revenue&lt;/li&gt;
&lt;li&gt;DeutschlandTicket&lt;/li&gt;
&lt;li&gt;FREE M Urban Sports Club&lt;/li&gt;
&lt;li&gt;Zusätzliche 3 Tage bezahlter Urlaub für ehrenamtliche Tätigkeiten oder Weiterbildung&lt;/li&gt;
&lt;li&gt;Wir investieren in deine Weiterentwicklung mit einem dafür vorgesehenen Budget&lt;/li&gt;
&lt;li&gt;Erweiterter Elternurlaub&lt;/li&gt;
&lt;li&gt;4 Wochen Sabbatical (nach 3 Jahren Zugehörigkeit)&lt;/li&gt;
&lt;li&gt;Unterstützung der psychischen Gesundheit durch Plumm&lt;/li&gt;
&lt;li&gt;Einmaliges Home-Office-Budget&lt;/li&gt;
&lt;li&gt;Arbeiten weltweit – bis zu 90 Tage außerhalb deines Heimatlandes&lt;/li&gt;
&lt;li&gt;Team-Events und soziale Aktivitäten&lt;/li&gt;
&lt;li&gt;Möglichkeit, dein Arbeitsgerät zu übernehmen (abhängig von der Berechtigung)&lt;/li&gt;
&lt;li&gt;25 Tage bezahlter Urlaub plus 5 optionale Tage unbezahlter Urlaub pro Jahr&lt;/li&gt;
&lt;li&gt;Barista im Office&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h3&gt;TIDE IS A PLACE FOR EVERYONE&lt;/h3&gt;
&lt;p&gt;At Tide, we believe that we can only succeed if we let our differences enrich our culture. Our Tideans come from a variety of backgrounds and experience levels. We consider everyone irrespective of their ethnicity, religion, sexual orientation, gender identity, family or parental status, national origin, veteran, neurodiversity or differently-abled status. We celebrate diversity in our workforce as a cornerstone of our success. Our commitment to a broad spectrum of ideas and backgrounds is what enables us to build products that resonate with our members’ diverse needs and lives.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;We are One Team and foster a transparent and inclusive environment, where everyone’s voice is heard.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;At Tide, we thrive on diversity, embracing various backgrounds and experiences. We welcome all individuals regardless of ethnicity, religion, sexual orientation, gender identity, or disability. Our inclusive culture is key to our success, helping us build products that meet our members&#39; diverse needs. We are One Team, committed to transparency and ensuring everyone’s voice is heard.&lt;/em&gt;&lt;/p&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&lt;strong&gt;Disclaimer&lt;/strong&gt;&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&lt;em&gt;It has come to our attention that individuals or agencies are falsely claiming to represent Tide and are reaching out to candidates regarding job opportunities. Please be aware that:&lt;/em&gt;&lt;/div&gt;
&lt;ul class=&quot;p-rich_text_list p-rich_text_list__bullet p-rich_text_list--nested&quot; data-stringify-type=&quot;unordered-list&quot; data-list-tree=&quot;true&quot; data-indent=&quot;0&quot; data-border=&quot;0&quot;&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;Tide does&amp;nbsp;&lt;strong data-stringify-type=&quot;bold&quot;&gt;not&lt;/strong&gt;&amp;nbsp;charge any fees at any stage of the recruitment process.&lt;/em&gt;&lt;/li&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;All official Tide job opportunities are listed exclusively on our&amp;nbsp;&lt;a href=&quot;https://www.tide.co/careers/&quot; target=&quot;_blank&quot;&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;Careers Page&lt;/strong&gt;&lt;/a&gt;&amp;nbsp;and applications should be submitted through this channel.&lt;/em&gt;&lt;/li&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;Communication from Tide will only come from an official&amp;nbsp;&lt;strong data-stringify-type=&quot;bold&quot;&gt;@tide&lt;/strong&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;.co&lt;/strong&gt;&amp;nbsp;email address.&lt;/em&gt;&lt;/li&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;Tide does not work with agencies or recruiters without prior formal engagement, and we do not authorize third parties to make job offers on our behalf.&lt;/em&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;If you are contacted by anyone misrepresenting Tide or requesting payment, please treat it as fraudulent and report it to us immediately at &lt;a ----- ----- safety and trust are important to us, and we are committed to ensuring a fair and transparent recruitment process.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;Tide leverages AI to enhance our hiring experience. You can read more about how we use AI in our recruitment process in our &lt;a href=&quot;https://assets.ctfassets.net/3h69mkdgxn20/5MFtWSdG8YLKq3jZkK52NY/3f18633073e6cdbd03bba4b9791c64f4/Using_AI_throughout_the_Hiring_Process.pdf&quot; target=&quot;_blank&quot;&gt;AI Policy&lt;/a&gt;.&lt;/em&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;Your personal data will be processed by Tide for recruitment purposes and in accordance with &lt;/em&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;&lt;a class=&quot;c-link&quot; href=&quot;https://assets.ctfassets.net/3h69mkdgxn20/30JAUcDJMlaCwUKt4zoW0j/dd541981a67b6838d6e54537704bc8aa/Tide_Recruitment_Privacy_Notice_Job_Post_Version.pdf&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://assets.ctfassets.net/3h69mkdgxn20/1MYf6q4ZMWugpeaROVETBN/526e9c160a2de03576413c81657c6466/Recruitment_Privacy_Notice__Final_Draft__Sep_2024_.pdf&quot; data-sk=&quot;tooltip_parent&quot;&gt;Tide&#39;s Recruitment Privacy Notice&lt;/a&gt;&lt;/em&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;.&lt;/em&gt;&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;Find Jobs in Germany on Arbeitnow

&lt;p&gt;Doctolib is looking for you to join us as a &lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Senior AI Specialist (x/f/m)&lt;/strong&gt; at our Berlin location, starting as soon as possible.&lt;/p&gt;
&lt;div class=&quot;whitespace-pre-wrap break-words font-normal first:pt-0 last:pb-0 py-1 @md:pt-2 @md:pb-[10px] @md:leading-relaxed text-base leading-relaxed text-foreground&quot;&gt;Doctolib is becoming an &lt;strong class=&quot;font-semibold text-foreground&quot;&gt;AI-native&lt;/strong&gt; company. We are redesigning the way we work, workflow by workflow, and are looking for people who will not only support this transformation, but actively build it. As a &lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Senior AI Specialist&lt;/strong&gt;, you will be the technical builder and &lt;strong class=&quot;font-semibold text-foreground&quot;&gt;AI Ops Owner&lt;/strong&gt; behind AI-powered productivity for our Operations and Customer Success teams.&lt;/div&gt;
&lt;div class=&quot;whitespace-pre-wrap break-words font-normal first:pt-0 last:pb-0 py-1 @md:pt-2 @md:pb-[10px] @md:leading-relaxed text-base leading-relaxed text-foreground&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;whitespace-pre-wrap break-words font-normal first:pt-0 last:pb-0 py-1 @md:pt-2 @md:pb-[10px] @md:leading-relaxed text-base leading-relaxed text-foreground&quot;&gt;You will work in &lt;strong class=&quot;font-semibold text-foreground&quot;&gt;founder and product mode&lt;/strong&gt;: you will own a workflow end to end, from context and agent design to evaluation, and continuously take it to a higher level of automation. Our ambition is to move away from manual case-by-case work towards workflows that run largely autonomously while maintaining a high quality bar. In this way, you will contribute directly to our mission of improving healthcare for everyone.&lt;/div&gt;
&lt;h2 class=&quot;pb-2 pt-4 heading-xl text-foreground&quot;&gt;Your Responsibilities&lt;/h2&gt;
&lt;ul&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Redesign workflows rather than simply automating them:&lt;/strong&gt;&amp;nbsp;You analyze the most critical Operations and Customer Success workflows, break down time-consuming processes that require limited judgment, and transform them through the use of AI agents. You set clear objectives for autonomy and quality, and continuously develop them further.&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Build and operate AI agents as products:&lt;/strong&gt;&amp;nbsp;You develop and manage agents on platforms such as Dust or Claude. Each agent is deployed to production with a defined baseline and relevant metrics such as benefit, usage, and scalability.&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Knowledge and context management:&lt;/strong&gt;&amp;nbsp;You deliberately curate the context agents need, from templates to core data. The guiding principle is quality over quantity. You ensure that knowledge sources in Confluence, Drive, or Salesforce are always up to date and well structured.&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Evaluation and quality assurance:&lt;/strong&gt;&amp;nbsp;You define quality standards and establish evaluation routines to identify and address weaknesses such as hallucinations or prompt drift at an early stage. You continuously optimize prompts through systematic user feedback and A/B testing.&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;CRM and data integration:&lt;/strong&gt;&amp;nbsp;You own the interfaces between CRM systems such as Salesforce and our AI platforms. You automate data flows and work closely with IT to unlock new, valuable data sources for our agents.&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Central interface and enablement:&lt;/strong&gt;&amp;nbsp;You translate business requirements into technical solutions and bring together stakeholders from Leadership, IT, and Product. You strengthen the team’s AI fluency in the areas of context, agent management, and evaluation.&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Impact and measurement:&lt;/strong&gt;&amp;nbsp;Rather than inventing new KPIs, you make the success of AI measurable using existing metrics such as time, quality, and cost, and use these insights to guide the next steps in scaling.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 class=&quot;pb-2 pt-4 heading-xl text-foreground&quot;&gt;Your Profile&lt;/h2&gt;
&lt;p&gt;&lt;em&gt;Since production-ready AI workflows and agent technologies are still relatively new, years of market experience are rare. We therefore deliberately prioritize &lt;strong class=&quot;font-semibold text-foreground&quot;&gt;potential over years of experience alone&lt;/strong&gt;. What matters to us is your ability to learn quickly, your strong product mindset, and your judgment. If you are passionate about this field and bring the necessary skills, we would be delighted to hear from you, even if your profile does not perfectly cover every single aspect.&lt;/em&gt;&lt;/p&gt;
&lt;h3 class=&quot;pb-2 pt-4 heading-xl text-foreground&quot;&gt;What Really Matters to Us, Regardless of the Specific Tool:&lt;/h3&gt;
&lt;ul&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Learning speed and a production mindset:&lt;/strong&gt;&amp;nbsp;You have taught yourself a new technical field from scratch and built something real that people actually used. You can describe precisely what went wrong, such as hallucinations, prompt drift, outdated data, or costs, and how you solved it.&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;An instinct for evaluation:&lt;/strong&gt;&amp;nbsp;You do not rely on something merely “looking good”. You define a quality bar and measure against it. For you, automation and quality go hand in hand.&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Ownership and communication:&lt;/strong&gt;&amp;nbsp;You take ownership of a problem end to end, prioritize rigorously, feel comfortable with ambiguity, and make technical topics understandable to non-technical stakeholders.&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Technical and data understanding:&lt;/strong&gt;&amp;nbsp;You can read and adapt scripts, understand APIs, webhooks, and automation tools such as Make, n8n, and Zapier, and know how CRM data, ideally Salesforce data, flows into AI systems.&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Strong communication skills:&lt;/strong&gt;&amp;nbsp;You have a confident command of English and can operate at the highest level in our international environment. German at B1 level is sufficient.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 class=&quot;pb-2 pt-4 heading-xl text-foreground&quot;&gt;We Are Particularly Interested in:&lt;/h3&gt;
&lt;ul&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Expertise with agent platforms:&lt;/strong&gt;&amp;nbsp;You have practical experience with systems such as Dust, Claude, or LangChain. Since tools evolve quickly, we primarily rely on your process understanding and evaluation skills as a sustainable foundation.&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Technical depth and data fluency:&lt;/strong&gt;&amp;nbsp;You are proficient in languages such as Python or JavaScript and can confidently navigate Salesforce architectures or BI environments such as Tableau and Metabase to manage data flows effectively.&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;&lt;strong class=&quot;font-semibold text-foreground&quot;&gt;Operations experience:&lt;/strong&gt;&amp;nbsp;You have solid experience working with scaled Customer Success or Operations teams and understand their specific dynamics.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 class=&quot;pb-2 pt-4 heading-xl text-foreground&quot;&gt;What We Offer&lt;/h2&gt;
&lt;ul&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;A Germany-wide public transport pass sponsored by Doctolib if you work from the office or in hybrid mode&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Company-sponsored health insurance with excellent additional benefits&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;28 days of paid vacation, plus one additional day for every full calendar year of employment, up to a maximum of 30 days&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Participation in Doctolib’s long-term employee equity program, DoctoGrowth&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;The opportunity to work from abroad for up to 10 days per year&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;An occupational pension scheme with an employer contribution of 40%, or 15% during the probationary period&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;The Doctolib Parent Care Program, which includes one additional month of parental leave and much more&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Free mental health and coaching sessions through an external partner&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;In addition to healthy snacks and a regular breakfast buffet, we offer meal vouchers&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;A subsidized sports program with our partner Urban Sports Club&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;For caregivers and employees with disabilities, we offer support that includes more flexible working hours, additional leave for medical reasons, and psychological support&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 class=&quot;pb-2 pt-4 heading-xl text-foreground&quot;&gt;The Interview Process&lt;/h2&gt;
&lt;ul&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Interview with Talent&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Hiring Manager interview&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;On-site case study&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Final interview with VP&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Reference checks&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Offer&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Job Details&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Permanent position&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Full-time&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Location: Berlin&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Start date: July&lt;/li&gt;
&lt;li class=&quot;break-words text-foreground text-base leading-relaxed&quot;&gt;Hybrid, 2 days working from home per week&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&quot;whitespace-pre-wrap break-words font-normal first:pt-0 last:pb-0 py-1 @md:pt-2 @md:pb-[10px] @md:leading-relaxed text-base leading-relaxed text-foreground&quot;&gt;&lt;em&gt;Our vision is to improve the health of everyone. This is also reflected in our recruitment process. We evaluate applications exclusively on the basis of qualifications and motivation. We do not tolerate discrimination.&lt;/em&gt;&lt;/div&gt;
&lt;div class=&quot;whitespace-pre-wrap break-words font-normal first:pt-0 last:pb-0 py-1 @md:pt-2 @md:pb-[10px] @md:leading-relaxed text-base leading-relaxed text-foreground&quot;&gt;&lt;em&gt;The more diverse our team and ideas are, the more our product can contribute to improving the health of our users. That is why we invite you to apply, regardless of gender, religion, age, sexual orientation, ethnic origin, or disability.&lt;/em&gt;&lt;/div&gt;
&lt;div class=&quot;whitespace-pre-wrap break-words font-normal first:pt-0 last:pb-0 py-1 @md:pt-2 @md:pb-[10px] @md:leading-relaxed text-base leading-relaxed text-foreground&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;whitespace-pre-wrap break-words font-normal first:pt-0 last:pb-0 py-1 @md:pt-2 @md:pb-[10px] @md:leading-relaxed text-base leading-relaxed text-foreground&quot;&gt;&lt;em&gt;To ensure equal opportunities, you may omit information such as photos, age, and similar details from your application. Please let us know what accommodations we can make to support you in the best possible way.&lt;/em&gt;&lt;/div&gt;
&lt;div class=&quot;whitespace-pre-wrap break-words font-normal first:pt-0 last:pb-0 py-1 @md:pt-2 @md:pb-[10px] @md:leading-relaxed text-base leading-relaxed text-foreground&quot;&gt;&lt;em&gt;We look forward to digitalizing healthcare together with you!&lt;/em&gt;&lt;/div&gt;
&lt;div class=&quot;whitespace-pre-wrap break-words font-normal first:pt-0 last:pb-0 py-1 @md:pt-2 @md:pb-[10px] @md:leading-relaxed text-base leading-relaxed text-foreground&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;whitespace-pre-wrap break-words font-normal first:pt-0 last:pb-0 py-1 @md:pt-2 @md:pb-[10px] @md:leading-relaxed text-base leading-relaxed text-foreground&quot;&gt;&lt;em&gt;All information provided will be processed by Doctolib for application management purposes. For details on data processing, please click &lt;a class=&quot;break-all font-semibold transition-all duration-200 ease-in-out hover:underline text-highlight hover:text-highlight-400 active:text-highlight-dark&quot; href=&quot;https://doctolib.legal/B2C-Privacy-Policy-Career-DE&quot; target=&quot;_blank&quot;&gt;here&lt;/a&gt;. If you have any questions or would like to exercise your rights, please contact hr.dataprivacy(at)&lt;a class=&quot;break-all font-semibold transition-all duration-200 ease-in-out hover:underline text-highlight hover:text-highlight-400 active:text-highlight-dark&quot; href=&quot;http://doctolib.com/&quot; target=&quot;_blank&quot;&gt;doctolib.com&lt;/a&gt;.&lt;/em&gt;&lt;/div&gt;
&lt;section class=&quot;account-page__wrapper page-layout page-layout--primary-panel-workspace page-layout--medium&quot; data-test-settings-wrapper=&quot;&quot; data-test-page-layout=&quot;&quot;&gt;
&lt;div class=&quot;page-layout__grid-container&quot;&gt;
&lt;div class=&quot;page-layout__workspace&quot; data-test-page-layout-workspace=&quot;&quot;&gt;
&lt;div class=&quot;account-page-workspace-content&quot; data-test-account-page-workspace=&quot;&quot; data-artdeco-is-focused=&quot;true&quot;&gt;
&lt;div class=&quot;setting-container&quot;&gt;
&lt;div class=&quot;setting-group&quot; data-test-promotion-settings-page=&quot;&quot;&gt;
&lt;div class=&quot;setting-group__list&quot;&gt;
&lt;div class=&quot;ember-view setting-group-item promotion-settings-page__item&quot; data-test-selector=&quot;setting-group-item&quot;&gt;
